import{_ as r,l as i,o as a,c as n,v as e,p as _,x as l,d,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"DeltaNet","description":"","frontmatter":{"title":"DeltaNet","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/delta-net.md","filePath":"llm/delta-net.md","lastUpdated":1789023840000}'),p={name:"llm/delta-net.md"};function m(u,t,c,b,S,f){const o=i("Mermaid");return a(),n("div",null,[t[1]||(t[1]=e('<h1 id="deltanet" tabindex="-1">DeltaNet <a class="header-anchor" href="#deltanet" aria-label="Permalink to &quot;DeltaNet&quot;">​</a></h1><div class="epigraph"><p>先读出当前键上的旧值，再按写入强度插值后写回；联想记忆的更新于是变成一条 delta 规则，而不是只做加法。</p><footer>—— 对照 Schlag et al., 2021；并行算法见 Yang et al., NeurIPS 2024</footer></div><p>线性注意力把过去收成 \\(S_t=\\sum_i v_i k_i^\\top\\)，新联想只做加法，键一多就碰撞。<a href="/llm/linear-attention">Linear Attention</a> 写核化；<a href="/llm/infini-attn-paper">Infini-Attention</a> 把 delta 当作长程记忆的一种写法。本篇写 DeltaNet 本身：Schlag、Irie 与 Schmidhuber 2021 年的快速权重更新，以及 Yang、Wang、Zhang、Shen 与 Kim 2024 年如何用 Householder 的紧凑 WY 表示把逐步递推变成沿序列可分块并行。没有后者，前者停在小规模翻译与合成检索。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加法记忆不能释放槽位。序列长于键维之后，新 \\(vk^\\top\\) 叠在旧方向上，检索变成叠加。模型需要按<em>当前键</em>去改对应的值，而不是给所有键加一份外积。Widrow–Hoff / delta 规则正是：预测错了多少，就沿该输入方向改多少。</p><p>Schlag 等人把这条规则接到线性 Transformer 上，合成联想与小规模语言建模优于普通线性注意力。算法是逐步的：每步依赖 \\(S_{t-1}k_t\\)，不能直接套线性注意力的块内并行。Katharopoulos 式线性时间、常数内存的循环实现仍然沿长度串行，Tensor Core 吃不满，扩不到十亿参数、千亿 token。2024 年的问题因此是算法工程：在不物化每步 \\(d\\times d\\) 状态的前提下，沿长度并行。</p><p><span class="marginnote">DeltaNet 不是 Mamba。Mamba 的选择在离散化与状态维上；DeltaNet 的选择在「读旧值、写残差」这条键相关改写。对照应是线性注意力 / GLA，不要写成 SSM 的一个超参。</span></p><h3 id="快速权重视角" tabindex="-1">快速权重视角 <a class="header-anchor" href="#快速权重视角" aria-label="Permalink to &quot;快速权重视角&quot;">​</a></h3><p>\\(S\\) 是测试时更新的权重矩阵，\\(o_t=S_t q_t\\) 是用该权重做一次线性读。加法规则是 Hebb 式外积；delta 规则是对 \\(\\|S k-v\\|^2\\) 的一步梯度。Irie 等人把这类层叫做 fast weight programmers。规模化之前，这条线的证据在小模型与合成任务；规模化之后，才谈得上与 Mamba、GLA 比困惑度。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="更新公式" tabindex="-1">更新公式 <a class="header-anchor" href="#更新公式" aria-label="Permalink to &quot;更新公式&quot;">​</a></h3><p>令 \\(v_t^{\\mathrm{old}}=S_{t-1}k_t\\)，写入强度 \\(\\beta_t=\\sigma(W_\\beta x_t)\\in(0,1)\\)，</p> \\[v_t^{\\mathrm{new}}=\\beta_t v_t+(1-\\beta_t)v_t^{\\mathrm{old}}, \\]\\[S_t=S_{t-1}-v_t^{\\mathrm{old}}k_t^\\top+v_t^{\\mathrm{new}}k_t^\\top=S_{t-1}(I-\\beta_t k_tk_t^\\top)+\\beta_t v_tk_t^\\top. \\]<p>\\(\\beta_t=1\\) 时旧值沿 \\(k_t\\) 被换掉；\\(\\beta_t=0\\) 时状态不动。输出仍是 \\(o_t=S_t q_t\\)。递推矩阵 \\(I-\\beta_t kk^\\top\\) 是广义 Householder。逐步复杂度仍 \\(O(Ld^2)\\)，与加法线性注意力同阶，常数更大，因为多一次读旧值。</p><h3 id="分块-wy-沿长度并行" tabindex="-1">分块 WY：沿长度并行 <a class="header-anchor" href="#分块-wy-沿长度并行" aria-label="Permalink to &quot;分块 WY：沿长度并行&quot;">​</a></h3><p>Yang 等人指出 \\(S_t=\\sum_{i\\le t} u_i k_i^\\top\\)，伪值 \\(u_i=\\beta_i(v_i-v_i^{\\mathrm{old}})\\)。块内 Householder 连乘用紧凑 WY：</p> \\[P_{[t]}^r=I-\\sum_{i=1}^r w_{[t]}^i k_{[t]}^{i\\top}, \\]<p>\\(w,u\\) 由块内严格下三角系统一次解出（UT / WY），再</p> \\[S_{[t+1]}=S_{[t]}P_{[t]}+H_{[t]},\\quad O_{[t]}=Q_{[t]}S_{[t]}^\\top+(Q_{[t]}K_{[t]}^\\top\\odot M)(\\cdots). \\]<p>块间只传 \\(d\\times d\\) 状态，块内是 GEMM 与一个 \\(C\\times C\\) 三角结构，\\(C\\) 取 64/128。前向反向都沿长度并行。库实现见 Flash Linear Attention。</p><p>1.3B / 100B token 上，作者报 DeltaNet 的语言建模与零样本优于同设定的 Mamba 与 GLA；合成与真实检索基准上同样。每隔一层滑窗、或加两层全局注意力的混合，可超过普通 Transformer 对照。长度外推相对 GLA / RetNet 弱，作者推测就是缺少显式衰减——这直接指向 <a href="/llm/gated-delta-net">Gated DeltaNet</a>。</p>',21)),(a(),_(h,null,{default:l(()=>[s(o,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22S_%7Bt-1%7D%22%5D%20--%3E%20READ%5B%22v_old%20%3D%20S%20k_t%22%5D%0A%20%20READ%20--%3E%20MIX%5B%22v_new%20%3D%20%CE%B2%20v%20%2B%20(1-%CE%B2)%20v_old%22%5D%0A%20%20MIX%20--%3E%20WR%5B%22S_t%20%3D%20S%20%E2%88%92%20v_old%20k%E1%B5%80%20%2B%20v_new%20k%E1%B5%80%22%5D%0A%20%20WR%20--%3E%20PAR%5B%22WY%20%E5%88%86%E5%9D%97%EF%BC%9A%E5%9D%97%E5%86%85%E5%B9%B6%E8%A1%8C%E3%80%81%E5%9D%97%E9%97%B4%E4%BC%A0%20S%22%5D%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="为什么碰撞会减轻" tabindex="-1">为什么碰撞会减轻 <a class="header-anchor" href="#为什么碰撞会减轻" aria-label="Permalink to &quot;为什么碰撞会减轻&quot;">​</a></h3><p>加法把所有键的值堆在同一矩阵里，读 \\(Sq\\) 是叠加。Delta 沿 \\(k_t\\) 做一次秩一修正，近似「覆盖该地址」。键不正交时覆盖会漏到邻居，这是线性记忆的硬限制，不是实现 bug。\\(\\beta_t\\) 提供软覆盖：重复出现的键可以逐步改写，而不必一步抹掉不确定的旧值。</p><p>Householder 连乘若逐步做，每步都写 \\(d\\times d\\)，带宽打满。WY 把连乘收成 \\(C\\) 个 \\(d\\) 维向量，IO 从 \\(O(C d^2)\\) 降到 \\(O(C d)\\) 量级再加块内 GEMM，这才和 FlashAttention 争占用。没有这步，DeltaNet 只是一条好看的 RNN。</p><p><span class="marginnote">\\(\\beta_t\\) 取到 \\((0,2)\\) 会引入负特征值，后续工作用来讨论状态跟踪。2021/2024 主实验把 \\(\\beta\\) 放在 \\((0,1)\\)。复现时不要默认打开负区间。</span></p><h3 id="混合层补的是地址而不是门控" tabindex="-1">混合层补的是地址而不是门控 <a class="header-anchor" href="#混合层补的是地址而不是门控" aria-label="Permalink to &quot;混合层补的是地址而不是门控&quot;">​</a></h3><p>滑窗给局部 softmax 尖峰；两层全局注意力给全文精确读。这与「给 delta 加 \\(\\alpha_t\\)」不同：混合是改层类型，门控是改同一循环核。2024 文的混合说明纯 DeltaNet 在真实语言上仍缺某种精确检索；2025 的门控说明它还缺遗忘。两条后续不要并成一句。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>头维受 SRAM 限制时状态偏小，召回先掉。作者提到分块对角 Householder 作为可能出路。无衰减则远距离信息清不掉也淡不掉，文档拼接任务会脏。逐步推理很便宜，训练必须用分块核；用 PyTorch 循环训 1.3B 不现实。</p><p>不要把 2024 的 1.3B/100B 写成已经替代 7B Transformer。混合超过 Transformer 的声明绑在作者的对照设定上。Infini-Attention 里的 delta 是压缩记忆的一种更新，与作为主干层的 DeltaNet 共享规则、不共享系统栈。</p><p>数值上 \\(I-\\beta kk^\\top\\) 要求键的尺度受控，通常对 \\(k\\) 做归一。未归一时 Householder 不再是收缩，状态会炸。短卷积等局部卷积是实现里常见附加，不是 2021 公式的一部分，消融要分开报。</p><p>并行算法的关键不在又一条 RNN 公式，而在承认 \\(S_t\\) 仍可写成 \\(\\sum u_ik_i^\\top\\)。一旦伪值 \\(u_i\\) 能在块内用三角系统解出，其余与普通线性注意力的 chunkwise 相同：块间扫描状态，块内 \\((QK^\\top\\odot M)\\) 乘伪值。这解释了为何 FLA 库能把 DeltaNet 和 GLA 放在同一套占用里。块长 \\(C\\) 太大，三角解 \\(C\\times C\\) 变贵且占用 SRAM；太小则扫描步数变多。实践中 \\(C\\) 与头维一起受片上存储约束，这才是「1.3B 能训、再大要分块对角」的来源。</p><p>相对 softmax，DeltaNet 仍然没有竞争归一化，多键可以同时以大内积贡献。检索强于加法线性核，是因为覆盖减少碰撞，不是因为恢复了单纯形尖峰。合成联想任务上的优势不应直接读成「已可替换满注意力做 RAG」：真实检索还涉及需要精确拷贝的稀有字符串，混合层或门控往往仍必要。</p><p><span class="marginnote">引用时区分 Schlag et al. 2021（规则与小规模证据）与 Yang et al. 2024（并行算法与 1.3B）。只写「DeltaNet 2024」会把快速权重的来源抹掉。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DeltaNet 用 delta 规则沿当前键读旧值、写新值，减轻加法线性记忆的碰撞。</li><li>更新是广义 Householder；逐步形式无法沿长度吃满 GPU。</li><li>Yang 等人用紧凑 WY + 分块把训练变成块内 GEMM、块间传状态。</li><li>1.3B / 100B 上优于同设定 Mamba 与 GLA；混合注意力层可再抬下游。</li><li>缺少显式衰减，长度外推是已知弱点，由 Gated DeltaNet 补。</li><li>状态容量仍受头维限制；键需归一以保证收缩。</li><li>出处：Schlag, Irie, Schmidhuber，线性 Transformer 的 delta 规则，2021；Yang et al.，<em>Parallelizing Linear Transformers with the Delta Rule over Sequence Length</em>，NeurIPS 2024，arXiv:2406.06484。</li></ul>',16))])}const A=r(p,[["render",m]]);export{D as __pageData,A as default};
